    /// <summary>
    /// 獲取指定 ShowCase 頁面中指定索引的 ShowCaseItem 的源代碼
    /// </summary>
    /// <param name="className">ShowCase 類名</param>
    /// <param name="index">ShowCaseItem 的索引（從 0 開始）</param>
    /// <returns>AXAML 源代碼字符串，如果未找到則返回 null</returns>
    public static string? GetSourceCode(string className, int index)
    {
        if (_sourceCodes.TryGetValue(className, out var items))
        {
            if (items.TryGetValue(index, out var sourceCode))
            {
                return sourceCode;
            }
        }
        return null;
    }

    /// <summary>
    /// 獲取指定 ShowCase 頁面中指定索引的 ShowCaseItem 的源代碼
    /// </summary>
    /// <param name="showCaseType">ShowCase 頁面的類型</param>
    /// <param name="index">ShowCaseItem 的索引（從 0 開始）</param>
    /// <returns>AXAML 源代碼字符串，如果未找到則返回 null</returns>
    public static string? GetSourceCode(System.Type showCaseType, int index)
    {
        return GetSourceCode(showCaseType.Name, index);
    }

    /// <summary>
    /// 獲取指定 ShowCase 頁面的所有 ShowCaseItem 源代碼
    /// </summary>
    /// <param name="className">ShowCase 類名</param>
    /// <returns>索引到源代碼的字典，如果未找到則返回 null</returns>
    public static Dictionary<int, string>? GetAllSourceCodes(string className)
    {
        if (_sourceCodes.TryGetValue(className, out var items))
        {
            return new Dictionary<int, string>(items);
        }
        return null;
    }

    /// <summary>
    /// 獲取所有已註冊的 ShowCase 類名
    /// </summary>
    public static IEnumerable<string> GetAllShowCaseNames()
    {
        return _sourceCodes.Keys;
    }
}
